// Extracted by gdp-wired/extract from p12.py (Meter, a class and its methods).
// Checked against the code it was read from; read again with extract() after the code changes.
import {all, any, bool, forall, intern, nat, record, rule, when, yes} from 'gdp-wired'

export const meterRule = rule("Meter")
  .state({n: 0})
  .maps({a_: record({has: bool, value: nat}).from({has: false, value: 0}), b_: record({has: bool, value: nat}).from({has: false, value: 0})})
  .step(({b_, a_}) => {
    const t1 = b_.at(intern('k')).value
    return {n: when(all(b_.at(intern('k')).has, t1.eq(0).not()), t1, 0), a_: a_.set(intern('k'), {has: yes, value: 1})}
  })

// What every state of the code is: a law about every state is about the code's with these beside it.
export const meterInvariants = [meterRule.law("a_: a key it doesn't hold holds the defaults", ({a_}) => forall(k => any(a_.at(k).has, all(a_.at(k).value.eq(0))))), meterRule.law("b_: a key it doesn't hold holds the defaults", ({b_}) => forall(k => any(b_.at(k).has, all(b_.at(k).value.eq(0)))))]
